(function(){
  var RAMPS={
    standard:' .:-=+*#%@',
    detailed:" .'`^\",:;Il!i><~+_-?][}{1)(|\\/tfjrxnuvczXYUJCLQ0OZmwqpdbkhao*#MW&8%B@$",
    blocks:' \u2591\u2592\u2593\u2588',
    binary:' #',
    dots:' .\u00b7\u2022\u25cf'
  };
  function luma(r,g,b){ return 0.2126*r+0.7152*g+0.0722*b; }
  function fitSize(w,h,maxCols,charAspect){
    w=Math.max(1,w|0); h=Math.max(1,h|0);
    maxCols=Math.max(1,maxCols|0);
    charAspect=charAspect||0.5;
    var cols=Math.min(maxCols,w);
    var rows=Math.max(1,Math.round(h*(cols/w)*charAspect));
    return {cols:cols,rows:rows};
  }
  function sampleGrid(data,w,h,cols,rows){
    if(!data||!w||!h||!cols||!rows) return {error:'尺寸参数无效'};
    if(data.length<w*h*4) return {error:'像素数据长度不足'};
    var g=new Float64Array(cols*rows);
    for(var ry=0;ry<rows;ry++){
      var y0=Math.floor(ry*h/rows),y1=Math.max(y0+1,Math.floor((ry+1)*h/rows));
      for(var cx=0;cx<cols;cx++){
        var x0=Math.floor(cx*w/cols),x1=Math.max(x0+1,Math.floor((cx+1)*w/cols));
        var sum=0,n=0;
        for(var y=y0;y<y1;y++){
          for(var x=x0;x<x1;x++){
            var i=(y*w+x)*4,a=data[i+3]/255;
            sum+=luma(data[i],data[i+1],data[i+2])*a+255*(1-a);
            n++;
          }
        }
        g[ry*cols+cx]=n?Math.round(sum/n):255;
      }
    }
    return {value:{grid:g,cols:cols,rows:rows}};
  }
  function toAscii(grid,cols,rows,opt){
    opt=opt||{};
    if(opt.ramp===undefined) opt.ramp=RAMPS.standard;
    var ramp=opt.ramp;
    if(typeof ramp!=='string'||!ramp.length) return {error:'字符梯度不能为空'};
    if(!grid||grid.length<cols*rows) return {error:'灰度矩阵长度不足'};
    var inv=!!opt.invert, gam=opt.gamma||1, out=[];
    for(var y=0;y<rows;y++){
      var line='';
      for(var x=0;x<cols;x++){
        var v=grid[y*cols+x]/255;
        if(v<0)v=0; if(v>1)v=1;
        if(gam!==1) v=Math.pow(v,gam);
        if(!inv) v=1-v;
        var idx=Math.round(v*(ramp.length-1));
        line+=ramp.charAt(idx);
      }
      out.push(line);
    }
    return {value:{text:out.join('\n'),lines:out,cols:cols,rows:rows,chars:cols*rows}};
  }
  function render(data,w,h,opt){
    opt=opt||{};
    var fit=fitSize(w,h,opt.cols||80,opt.charAspect||0.5);
    var s=sampleGrid(data,w,h,fit.cols,fit.rows);
    if(s.error) return s;
    return toAscii(s.value.grid,fit.cols,fit.rows,opt);
  }
  var API={RAMPS:RAMPS,luma:luma,fitSize:fitSize,sampleGrid:sampleGrid,toAscii:toAscii,render:render};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__ImgAsciiForge__=API;
})();
